import java.util.NavigableMap;
import java.util.TreeMap;

public class TimeSeriesIndex {
    private final NavigableMap<Long, String> auditLog = new TreeMap<>();

    public void recordEvent(long timestamp, String eventDetails) {
        auditLog.put(timestamp, eventDetails);
    }

    public String getNearestPriorEvent(long targetTimestamp) {
        // Finds the floor entry efficiently in O(log N) time
        var entry = auditLog.floorEntry(targetTimestamp);
        return entry != null ? entry.getValue() : "No prior event found";
    }

    public NavigableMap<Long, String> getWindow(long startTime, long endTime) {
        // Inclusive start, exclusive end range query
        return auditLog.subMap(startTime, true, endTime, false);
    }
}
